namespace SIL.Motif.Generator.Emit;

/// <summary>
/// Emits the metathesis rule's structural-change setter. The payload names positions in the rule's structural
/// description, never the stored text, so LibLCM's own index writer keeps the stored form.
/// </summary>
public static class MetathesisRuleStrucChangeEmitter
{
    public static string Render() => """
        // <auto-generated>Produced by SIL.Motif.Generator emit. Do not hand-edit.</auto-generated>
        using System;
        using System.Collections.Generic;
        using System.Runtime.CompilerServices;
        using SIL.LCModel;
        using SIL.LCModel.Core.KernelInterfaces;
        using SIL.Motif.Contract.Ids;
        using SIL.Motif.Contract.Model;
        using SIL.Motif.Contract.Parsing;
        using SIL.Motif.Model.Effects;
        using SIL.Motif.Model.Snapshot;

        namespace SIL.Motif.Runner.Operations;

        /// <summary>The positions a metathesis rule's structural description plays, as FieldWorks stores them.</summary>
        public static class PhMetathesisRuleStrucChangeOperationKinds
        {
            public const string Set = "grammar/phMetathesisRule/setStrucChange";

            [ModuleInitializer]
            internal static void Register()
            {
                OperationKindRegistry.Register(Set);
                OperationHandlerRegistry.Register(Set, new MetathesisStrucChangeHandler());
                OperationSlotRegistry.RegisterScalar(Set, SnapshotFields.PhMetathesisRuleStrucChange);
            }
        }

        internal sealed class MetathesisStrucChangeHandler : IOperationHandler
        {
            public ExpectedEffect ApplyAndCaptureEffect(LcmCache cache, OperationEnvelope operation, List<CanonicalId> touchedTargets)
            {
                var after = operation.After ?? throw new InvalidOperationException("Metathesis structural change requires after.");
                ClosedPayloadParsing.RequireObject(after, operation.Kind);
                ClosedPayloadParsing.RejectUnknownProperties(after,
                    new[] { "leftEnvironment", "leftSwitch", "middle", "rightSwitch", "rightEnvironment", "middleWith" }, operation.Kind);
                var (id, rule) = TargetResolution.Resolve<IPhMetathesisRule>(cache, operation, operation.Kind);
                int Position(string name) => ClosedPayloadParsing.GetRequiredInteger(after, name, operation.Kind);
                var leftEnvironment = Position("leftEnvironment");
                var leftSwitch = Position("leftSwitch");
                var middle = Position("middle");
                var rightSwitch = Position("rightSwitch");
                var rightEnvironment = Position("rightEnvironment");
                var middleWithLeft = true;
                if (after.TryGetProperty("middleWith", out _))
                {
                    var side = ClosedPayloadParsing.GetRequiredString(after, "middleWith", operation.Kind);
                    if (side is not ("left" or "right"))
                        throw new InvalidOperationException($"'{operation.Kind}': 'middleWith' must be 'left' or 'right'.");
                    middleWithLeft = side == "left";
                }
                if (middle == -1 && after.TryGetProperty("middleWith", out _))
                    throw new InvalidOperationException($"'{operation.Kind}': 'middleWith' needs a middle position.");
                var count = rule.StrucDescOS.Count;
                if (leftSwitch < 0 || rightSwitch <= leftSwitch || rightSwitch >= count)
                    throw new InvalidOperationException($"'{operation.Kind}': a metathesis rule needs a left switch before a right switch inside its {count}-item structural description.");
                if (leftEnvironment != leftSwitch - 1 && !(leftEnvironment == -1 && leftSwitch == 0))
                    throw new InvalidOperationException($"'{operation.Kind}': the left environment must end directly before the left switch.");
                if (middle == -1 ? rightSwitch != leftSwitch + 1 : middle != leftSwitch + 1 || rightSwitch != middle + 1)
                    throw new InvalidOperationException($"'{operation.Kind}': the middle, when present, must lie directly between the switches, and nothing else may.");
                if (rightEnvironment == -1 ? rightSwitch != count - 1 : rightEnvironment != rightSwitch + 1 || rightEnvironment >= count)
                    throw new InvalidOperationException($"'{operation.Kind}': the right environment must start directly after the right switch and hold the remaining items.");
                var before = Read(rule);
                var indices = new int[5];
                indices[PhMetathesisRuleTags.kidxLeftEnv] = leftEnvironment;
                indices[PhMetathesisRuleTags.kidxLeftSwitch] = leftSwitch;
                indices[PhMetathesisRuleTags.kidxMiddle] = middle;
                indices[PhMetathesisRuleTags.kidxRightSwitch] = rightSwitch;
                indices[PhMetathesisRuleTags.kidxRightEnv] = rightEnvironment;
                rule.SetStrucChangeIndices(indices, middleWithLeft);
                touchedTargets.Add(id);
                return new ExpectedEffect(id, SnapshotFields.PhMetathesisRuleStrucChange, before, Read(rule));
            }

            public ExpectedEffect ReadCurrentFootprint(LcmCache cache, OperationEnvelope operation)
            {
                var (id, rule) = TargetResolution.Resolve<IPhMetathesisRule>(cache, operation, operation.Kind);
                var current = Read(rule);
                return new ExpectedEffect(id, SnapshotFields.PhMetathesisRuleStrucChange, current, current);
            }

            internal static Dictionary<string, string> Read(IPhMetathesisRule rule) =>
                string.IsNullOrEmpty(rule.StrucChange?.Text) ? new() : new()
                {
                    ["text"] = rule.StrucChange.get_NormalizedForm(FwNormalizationMode.knmNFSC).Text,
                };
        }

        """;
}
